from lib import *
S = SS('k82')
F1 = [['默认 Pod', 'uid=0, /data 777 root:root'], ['runAsUser 1000 / runAsGroup 3000', ''], ['fsGroup 2000', '/data 变 2777 root:2000'], ['新建文件', '1000:2000(setgid 继承组)']]
F2 = [['默认', '14 个能力'], ['drop ALL', '0 个,chown 失败'], ['add NET_ADMIN', '15 个,能建网卡'], ['privileged', '41 个,能 mount']]
F3 = [['allowPrivilegeEscalation: false', 'NoNewPrivs=1'], ['readOnlyRootFilesystem', '写 /tmp 失败'], ['挂载的卷', '仍可写']]
F4 = [['runAsNonRoot: true', '镜像是 root'], ['kubelet 拒绝', 'CreateContainerConfigError'], ['再加 runAsUser: 1000', 'Running,uid=1000']]
PANELS = [('f', 'flow', 'securityContext'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("默认 Pod:id 是 uid=0(root),emptyDir /data 权限 777 root:root,新建文件 0:0。设置 runAsUser: 1000、runAsGroup: 3000、fsGroup: 2000、supplementalGroups: [4000, 5000]:id 是 uid=1000 gid=3000 groups=2000,3000,4000,5000;/data 变成 2777 root:2000(组位置多了 setgid 位,组是 fsGroup);在里面新建的文件属于 1000:2000——继承了目录的组;/proc/1/status 的 Groups 是 2000 3000 4000 5000。", f=fl(F1, cur=[2], done=[0, 1, 3]), t=tl(S(1), mark=lidx(S(1), 'Pod user:id'), done=lidx(S(1), '2777', '1000:2000')), kv=KV([['runAsUser / runAsGroup', '进程的 uid、主 gid'], ['fsGroup', '卷的属组 + setgid,新文件继承'], ['supplementalGroups', '额外的附加组']], ['fsGroup'])),
    step("读 /proc/1/status 的 CapEff 解码:默认容器 14 个能力(CHOWN、DAC_OVERRIDE、FOWNER、FSETID、KILL、SETGID、SETUID、SETPCAP、NET_BIND_SERVICE、NET_RAW、SYS_CHROOT、MKNOD、AUDIT_WRITE、SETFCAP);drop: [ALL] 后 0 个;add: [NET_ADMIN] 多一个 NET_ADMIN 共 15 个;privileged: true 是 41 个全部。验证:默认里 chown 成功,drop ALL 里 Operation not permitted;默认里 ip link add 被拒,add NET_ADMIN 里成功;privileged 里能 mount tmpfs,默认里 permission denied。uid 1000 + drop ALL 监听 80 端口也成功:节点上 net.ipv4.ip_unprivileged_port_start=0。", f=fl(F2, cur=[0, 1, 2, 3]), t=tl(S(2), mark=lidx(S(2), 'caps-default:', 'caps-drop:', 'caps-add:', 'caps-priv:'), done=lidx(S(2), 'default 里 chown', 'ip link add', '监听 80')), kv=KV([['默认 14 个', 'containerd 的缺省能力集'], ['drop ALL', '最小权限的起点'], ['NET_BIND_SERVICE', '本环境 ip_unprivileged_port_start=0,不需要']], ['drop ALL'])),
    step("allowPrivilegeEscalation: false 让进程的 NoNewPrivs 从 0 变成 1(setuid 程序不能再提权)。readOnlyRootFilesystem: true 之后,写 /tmp 报 Read-only file system,但挂载的卷 /data 仍然可写——只读的是镜像层的根文件系统。", f=fl(F3, cur=[0, 1], done=[2]), t=tl(S(3), mark=lidx(S(3), 'NoNewPrivs'), done=lidx(S(3), 'readOnlyRootFilesystem')), kv=KV([['NoNewPrivs', 'setuid/文件能力都无法提权'], ['只读根', '写入要放到卷(emptyDir)里'], ['配合 drop ALL', 'restricted 配置的组合']], ['NoNewPrivs'])),
    step("runAsNonRoot: true 但 busybox 镜像默认用户是 root:Pod 卡在 Pending,容器状态 CreateContainerConfigError,message 是 container has runAsNonRoot and image will run as root。再加上 runAsUser: 1000:Running,id 是 uid=1000 gid=0(root) groups=0(root)。", f=fl(F4, cur=[1], done=[2], mark=[0]), t=tl(S(4), mark=lidx(S(4), 'CreateContainerConfigError'), done=lidx(S(4), 'phase=Running')), kv=KV([['runAsNonRoot', '是检查,不是切换用户'], ['镜像是 root', 'kubelet 在创建容器前就拒绝'], ['要配 runAsUser', '或者用本身非 root 的镜像']], ['runAsNonRoot'])),
]
A = mkartk('k82', 82, 'Kubernetes,securityContext,runAsUser,fsGroup,capabilities,真实验证,动画演示',
    '在 kind 集群里读 id、stat 和 /proc/1/status 验证 securityContext:runAsUser/runAsGroup/fsGroup/supplementalGroups 让 id 变成 uid=1000 gid=3000 groups=2000,3000,4000,5000,emptyDir 变成 2777 root:2000;默认容器 14 个能力、drop ALL 为 0、add NET_ADMIN 为 15、privileged 为 41;allowPrivilegeEscalation: false 让 NoNewPrivs=1;readOnlyRootFilesystem 只读根但卷可写;runAsNonRoot 遇到 root 镜像 CreateContainerConfigError。',
    'securityContext 里这些字段到底改变了进程的什么?fsGroup 为什么能让卷里的文件有一个固定的组?默认容器有哪些 Linux 能力?runAsNonRoot 是切换用户还是检查?这篇逐个实验,把 id、能力位和文件权限都读出来。',
    [('14 / 0 / 15 / 41', '默认、drop ALL、add NET_ADMIN、privileged 四种配置下容器的 Linux 能力个数'), ('2777 root:2000', '设置 fsGroup: 2000 后 emptyDir 的权限与属组(setgid 位让新文件继承组)'), ('CreateContainerConfigError', 'runAsNonRoot: true 遇到默认 root 镜像时的容器状态')],
    [('用户、组与卷的属组', '<p>默认 Pod:<code>id</code> 是 <code>uid=0(root)</code>,emptyDir <code>/data</code> 是 <code>777 root:root</code>。设置 <code>runAsUser: 1000</code>、<code>runAsGroup: 3000</code>、<code>fsGroup: 2000</code>、<code>supplementalGroups: [4000, 5000]</code>:<code>id</code> 变成 <code>uid=1000 gid=3000 groups=2000,3000,4000,5000</code>;<code>/data</code> 变成 <code>2777 root:2000</code>(<code>2</code> 是 setgid 位,组是 fsGroup);在里面新建的文件属于 <code>1000:2000</code>,继承了目录的组;<code>/proc/1/status</code> 的 <code>Groups</code> 是 <code>2000 3000 4000 5000</code>。</p>'),
     ('Linux 能力', '<p>读 <code>/proc/1/status</code> 的 <code>CapEff</code> 并解码:默认容器 14 个能力(<code>CHOWN</code>、<code>DAC_OVERRIDE</code>、<code>FOWNER</code>、<code>FSETID</code>、<code>KILL</code>、<code>SETGID</code>、<code>SETUID</code>、<code>SETPCAP</code>、<code>NET_BIND_SERVICE</code>、<code>NET_RAW</code>、<code>SYS_CHROOT</code>、<code>MKNOD</code>、<code>AUDIT_WRITE</code>、<code>SETFCAP</code>);<code>drop: [ALL]</code> 后是 0 个;<code>add: [NET_ADMIN]</code> 多出 <code>NET_ADMIN</code> 共 15 个;<code>privileged: true</code> 是全部 41 个。验证:默认里 <code>chown</code> 成功,drop ALL 里 <code>Operation not permitted</code>;默认里 <code>ip link add</code> 被拒,add NET_ADMIN 里成功;privileged 里能 <code>mount</code> tmpfs,默认里 <code>permission denied</code>。非 root(uid 1000)+ drop ALL 监听 80 端口也成功:节点上 <code>net.ipv4.ip_unprivileged_port_start=0</code>,所以不需要 <code>NET_BIND_SERVICE</code>。</p>'),
     ('防提权与只读根', '<p><code>allowPrivilegeEscalation: false</code> 让进程的 <code>NoNewPrivs</code> 从 0 变成 1(setuid 程序不能再提权)。<code>readOnlyRootFilesystem: true</code> 之后,写 <code>/tmp</code> 报 <code>Read-only file system</code>,但挂载的卷 <code>/data</code> 仍可写——只读的是镜像层的根文件系统,要写的目录得挂卷。</p>'),
     ('runAsNonRoot', '<p><code>runAsNonRoot: true</code> 遇到默认 root 用户的 busybox 镜像:Pod 卡在 <code>Pending</code>,容器状态 <code>CreateContainerConfigError</code>,message 是 <code>container has runAsNonRoot and image will run as root</code>。它是检查而不是切换用户。再加 <code>runAsUser: 1000</code> 就能 <code>Running</code>,<code>id</code> 是 <code>uid=1000 gid=0(root) groups=0(root)</code>。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,containerd v2.3.4 默认能力集);容器是 busybox:1.36;能力位解码用 CAP_* 名字表(0~40),CapEff 取自容器里 /proc/1/status;各验证命令用 kubectl exec 执行;每种情形各一次',
     '没有验证:fsGroupChangePolicy: OnRootMismatch 对大卷的影响;seccompProfile 与 AppArmor / SELinux;sysctls 的安全/不安全分类;appArmorProfile 字段;supplementalGroupsPolicy;Windows 的 securityContext;ambient / inheritable / bounding 能力集的细节;能力在 setuid 程序上的交互'],
    'securityContext', PANELS)
